const getTripPhotoChronologicalValue = (photo, fallbackIndex = 0) => {
  const createdAt = Date.parse(String(photo?.created_at || photo?.createdAt || '').trim());
  if (Number.isFinite(createdAt) && createdAt > 0) return createdAt;
  return fallbackIndex;
};

const getTripPhotoDateKey = (photo) => {
  const explicitDate = String(photo?.date || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(explicitDate)) return explicitDate;
  if (explicitDate) {
    const parsedExplicitDate = parseTripPhotoDateCandidate(explicitDate);
    if (parsedExplicitDate) return formatDateKeyFromDate(parsedExplicitDate);
  }

  const timestampCandidates = [
    photo?.taken_at,
    photo?.takenAt,
    photo?.created_at,
    photo?.createdAt,
    photo?.timestamp,
    photo?.uploaded_at,
  ];
  for (const candidate of timestampCandidates) {
    const parsed = parseTripPhotoDateCandidate(candidate);
    if (parsed) return formatDateKeyFromDate(parsed);
  }
  return '';
};

const sortTripPhotosChronologically = (photos = []) => (
  [...(Array.isArray(photos) ? photos : [])].sort((a, b) => {
    const diff = getTripPhotoChronologicalValue(a) - getTripPhotoChronologicalValue(b);
    if (diff !== 0) return diff;
    return String(a?.id || '').localeCompare(String(b?.id || ''));
  })
);

const handleTripPhotoImageError = (event) => {
  const fallbackUrl = String(event?.currentTarget?.dataset?.fallbackSrc || '').trim();
  if (!fallbackUrl) return;
  if (String(event?.currentTarget?.src || '').trim() === fallbackUrl) return;
  event.currentTarget.src = fallbackUrl;
};

// Supabase storage wrapper
const storage = {
  get: async (key, shared = false) => {
    if (
      key === 'calendar-user' ||
      key === 'calendar-title' ||
      key.includes('notification') ||
      key.startsWith('notify-')
    ) {
      const value = localStorage.getItem(key);
      return value ? { key, value, shared } : null;
    }
    return { key, value: null, shared };
  },
  set: async (key, value, shared = false) => {
    if (key === 'calendar-user' || key.includes('notification') || key === 'calendar-title') {
      localStorage.setItem(key, value);
      return { key, value, shared };
    }
    return { key, value, shared: true };
  }
};

