const parseJourneyTags = (value) => {
  const seen = new Set();
  return String(value || '')
    .split(',')
    .map((tag) => String(tag || '').trim().toLowerCase())
    .filter((tag) => {
      if (!tag || seen.has(tag)) return false;
      seen.add(tag);
      return true;
    });
};

const countJourneyJournalDays = (entries, goalId) => {
  const normalizedGoalId = String(goalId || '').trim();
  if (!normalizedGoalId) return 0;
  return new Set(
    (Array.isArray(entries) ? entries : [])
      .filter((entry) => String(entry?.goalId || '').trim() === normalizedGoalId)
      .filter((entry) => entry?.type === 'log' || entry?.type === 'note')
      .map((entry) => String(entry?.entryDate || String(entry?.createdAt || '').slice(0, 10)).trim())
      .filter(Boolean)
  ).size;
};

const getJourneyJournalPromptRotation = (entryDateValue, prompts = JOURNEY_JOURNAL_PROMPTS, count = JOURNEY_JOURNAL_PROMPTS_PER_DAY) => {
  const promptList = Array.isArray(prompts) ? prompts.filter(Boolean) : [];
  if (promptList.length <= count) return promptList;
  const dateKey = String(entryDateValue || new Date().toISOString().slice(0, 10)).trim();
  const seed = Array.from(dateKey).reduce((total, char) => total + char.charCodeAt(0), 0);
  const startIndex = seed % promptList.length;
  return Array.from({ length: Math.min(count, promptList.length) }, (_, index) => promptList[(startIndex + index) % promptList.length]);
};

const readJourneyPhotoFile = (file) => new Promise((resolve, reject) => {
  if (!file) {
    resolve({ photoUrl: '', photoName: '' });
    return;
  }
  const reader = new FileReader();
  reader.onerror = () => reject(new Error('photo_read_failed'));
  reader.onload = () => {
    const img = new Image();
    img.onerror = () => resolve({
      photoUrl: typeof reader.result === 'string' ? reader.result : '',
      photoName: String(file.name || 'Photo'),
    });
    img.onload = () => {
      const maxSize = 960;
      const scale = Math.min(1, maxSize / Math.max(img.width || 1, img.height || 1));
      const width = Math.max(1, Math.round((img.width || 1) * scale));
      const height = Math.max(1, Math.round((img.height || 1) * scale));
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext('2d');
      if (!context) {
        resolve({
          photoUrl: typeof reader.result === 'string' ? reader.result : '',
          photoName: String(file.name || 'Photo'),
        });
        return;
      }
      context.drawImage(img, 0, 0, width, height);
      resolve({
        photoUrl: canvas.toDataURL('image/jpeg', 0.78),
        photoName: String(file.name || 'Photo'),
      });
    };
    img.src = typeof reader.result === 'string' ? reader.result : '';
  };
  reader.readAsDataURL(file);
});

const deferJourneyOverlayOpen = (callback) => {
  if (typeof window === 'undefined') {
    callback();
    return;
  }
  window.setTimeout(callback, 0);
};

const normalizeJourneyNumber = (value) => {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : 0;
};

const getJourneyGoalProgress = (goal) => {
  const current = Math.max(0, normalizeJourneyNumber(goal?.current));
  const target = Math.max(0, normalizeJourneyNumber(goal?.target));
  if (!target) return 0;
  return Math.max(0, Math.min(1, current / target));
};

const formatJourneyProgressText = (goal) => {
  if (!goal) return '';
  const current = normalizeJourneyNumber(goal.current);
  const target = normalizeJourneyNumber(goal.target);
  const unit = String(goal.unit || '').trim();
  const formatValue = (value) => {
    if (!Number.isFinite(value)) return '0';
    return Number.isInteger(value) ? String(value) : value.toFixed(1).replace(/\.0$/, '');
  };
  if (!target && !unit) return formatValue(current);
  return `${formatValue(current)} / ${formatValue(target)}${unit ? ` ${unit}` : ''}`;
};

const formatJourneyTemplateLabel = (template) => `${template?.emoji ? `${template.emoji} ` : ''}${template?.label || ''}`.trim();

const getJourneyGoalEmoji = (goal) => {
  const title = String(goal?.title || '').toLowerCase();
  const unit = String(goal?.unit || '').toLowerCase();
  const combined = `${title} ${unit}`;
  if (/(run|walk|mile)/.test(combined)) return '🏃';
  if (/(work ?out|gym|exercise|fitness|workouts?)/.test(combined)) return '💪';
  if (/(lose weight|pound|lbs?|kg|kilogram)/.test(combined)) return '⚖️';
  if (/(save|\$|dollar|money|budget)/.test(combined)) return '💰';
  if (/(journal|write|writing|diary)/.test(combined)) return '📓';
  return '✨';
};

const getJourneyGoalType = (goal) => {
  const explicitType = String(goal?.goalType || '').trim();
  if (explicitType) return explicitType;
  const title = String(goal?.title || '').toLowerCase();
  const unit = String(goal?.unit || '').toLowerCase();
  const combined = `${title} ${unit}`;
  if (/(run|walk|mile)/.test(combined)) return 'run_walk';
  if (/(work ?out|gym|exercise|fitness|workouts?)/.test(combined)) return 'workout';
  if (/(lose weight|pound|lbs?|kg|kilogram)/.test(combined)) return 'lose_weight';
  if (/(save|\$|dollar|money|budget)/.test(combined)) return 'save_money';
  if (/(journal|write|writing|diary)/.test(combined)) return 'journal';
  return 'custom';
};

