const mergeAuthUserPreservingProfilePhoto = (nextAuthUser, previousAuthUser, preservedPhotoUrl = '') => {
  if (!nextAuthUser) return null;
  const nextPhotoUrl = getUserProfilePhotoUrl(nextAuthUser);
  if (nextPhotoUrl) return nextAuthUser;

  const fallbackPhotoUrl = String(
    preservedPhotoUrl
    || getStableAvatarPublicUrl(nextAuthUser?.id || previousAuthUser?.id || '')
    || getUserProfilePhotoUrl(previousAuthUser)
    || readCachedProfilePhotoUrl(nextAuthUser?.id || previousAuthUser?.id || '')
    || ''
  ).trim();
  if (!fallbackPhotoUrl) return nextAuthUser;

  return {
    ...nextAuthUser,
    avatar_url: fallbackPhotoUrl,
    picture: fallbackPhotoUrl,
    user_metadata: {
      ...(nextAuthUser?.user_metadata || {}),
      avatar_url: fallbackPhotoUrl,
      avatarUrl: fallbackPhotoUrl,
      picture: fallbackPhotoUrl,
      photo_url: fallbackPhotoUrl,
      photoURL: fallbackPhotoUrl,
    },
    raw_user_meta_data: {
      ...(nextAuthUser?.raw_user_meta_data || {}),
      avatar_url: fallbackPhotoUrl,
      avatarUrl: fallbackPhotoUrl,
      picture: fallbackPhotoUrl,
      photo_url: fallbackPhotoUrl,
      photoURL: fallbackPhotoUrl,
    },
  };
};
const UserProfileAvatar = ({
  photoUrl,
  userId = '',
  label,
  sizeClass = 'w-10 h-10',
  roundedClass = 'rounded-xl',
  borderClass = 'border border-purple-200 dark:border-gray-600',
  textClass = 'text-sm',
}) => {
  const cachedPhotoUrl = normalizeProfilePhotoUrl(readCachedProfilePhotoUrl({ id: userId }));
  const preferredPhotoUrl = normalizeProfilePhotoUrl(photoUrl || cachedPhotoUrl || '');
  const [displayPhotoUrl, setDisplayPhotoUrl] = React.useState(preferredPhotoUrl);
  const lastGoodPhotoUrlRef = React.useRef(preferredPhotoUrl);
  React.useEffect(() => {
    if (preferredPhotoUrl) {
      lastGoodPhotoUrlRef.current = preferredPhotoUrl;
      setDisplayPhotoUrl(preferredPhotoUrl);
      return;
    }
    if (lastGoodPhotoUrlRef.current) {
      setDisplayPhotoUrl(lastGoodPhotoUrlRef.current);
      return;
    }
    setDisplayPhotoUrl('');
  }, [preferredPhotoUrl]);
  const initial = String(label || '?').trim().charAt(0).toUpperCase() || '?';
  if (displayPhotoUrl) {
    return (
      <img
        src={displayPhotoUrl}
        alt="Profile"
        className={`${sizeClass} ${roundedClass} object-cover ${borderClass}`}
        onLoad={() => {
          const normalized = String(displayPhotoUrl || '').trim();
          if (!normalized) return;
          lastGoodPhotoUrlRef.current = normalized;
          writeCachedProfilePhotoUrl({ id: userId }, normalized);
        }}
        onError={() => {
          const fallbackPhotoUrl = String(lastGoodPhotoUrlRef.current || cachedPhotoUrl || '').trim();
          if (fallbackPhotoUrl && fallbackPhotoUrl !== displayPhotoUrl) {
            setDisplayPhotoUrl(fallbackPhotoUrl);
            return;
          }
          setDisplayPhotoUrl('');
        }}
      />
    );
  }
  return (
    <div className={`${sizeClass} ${roundedClass} bg-gradient-to-br from-rose-400 via-purple-400 to-indigo-400 flex items-center justify-center text-white font-bold ${textClass} shrink-0`}>
      {initial}
    </div>
  );
};

