const WIDGET_GRID_COLUMNS = 10;
const WIDGET_GRID_ROWS = 40;
const WIDGET_MIN_SIZE = 38;
const WIDGET_MAX_SIZE = 86;
const WIDGET_DEFAULT_SIZE = WIDGET_MIN_SIZE;
const HEADER_MODULE_IDS = Object.freeze(['icon', 'title', 'add', 'date']);
const HEADER_MODULE_DEFAULT_LAYOUT = Object.freeze({
  icon: { x: 9, y: 13, scale: 1 },
  title: { x: 79, y: 10, scale: 1 },
  date: { x: 79, y: 18, scale: 1 },
  add: { x: 88, y: 27, scale: 1 },
});
const createDefaultHeaderModuleLayout = () => ({
  icon: { ...HEADER_MODULE_DEFAULT_LAYOUT.icon },
  title: { ...HEADER_MODULE_DEFAULT_LAYOUT.title },
  date: { ...HEADER_MODULE_DEFAULT_LAYOUT.date },
  add: { ...HEADER_MODULE_DEFAULT_LAYOUT.add },
});
const normalizeHeaderModuleLayoutMap = (raw) => {
  let parsed = raw;
  if (typeof parsed === 'string') {
    try {
      parsed = JSON.parse(parsed);
    } catch {
      parsed = {};
    }
  }
  if (!parsed || typeof parsed !== 'object') parsed = {};
  const next = createDefaultHeaderModuleLayout();
  const xStep = 100 / Math.max(1, (WIDGET_GRID_COLUMNS - 1));
  const yStep = 100 / Math.max(1, (WIDGET_GRID_ROWS - 1));
  const snap = (value, step) => Math.round(Number(value || 0) / step) * step;
  HEADER_MODULE_IDS.forEach((id) => {
    const src = parsed?.[id];
    if (!src || typeof src !== 'object') return;
    const x = Math.max(2, Math.min(98, snap(Number(src?.x), xStep)));
    const y = Math.max(2, Math.min(98, snap(Number(src?.y), yStep)));
    const scale = id === 'add' ? 1 : Math.max(0.7, Math.min(1.8, Number(src?.scale)));
    if (Number.isFinite(x)) next[id].x = x;
    if (Number.isFinite(y)) next[id].y = y;
    if (Number.isFinite(scale)) next[id].scale = scale;
  });
  return next;
};
const readHeaderModuleLayoutFromPageTheme = (raw) => {
  let parsed = raw;
  if (typeof parsed === 'string') {
    try {
      parsed = JSON.parse(parsed);
    } catch {
      parsed = {};
    }
  }
  if (!parsed || typeof parsed !== 'object') parsed = {};
  return normalizeHeaderModuleLayoutMap(
    parsed?.headerModuleLayout || {
      icon: parsed?.iconOffset ? { ...parsed.iconOffset, scale: parsed?.iconScale } : undefined,
      title: parsed?.titleOffset ? { ...parsed.titleOffset, scale: parsed?.titleScale } : undefined,
      date: parsed?.dateOffset ? { ...parsed.dateOffset, scale: parsed?.dateScale } : undefined,
      add: parsed?.addOffset ? { ...parsed.addOffset, scale: 1 } : undefined,
    }
  );
};

const LAYER_CACHE_KEY = (uid) => `layer-cache-v1:${uid}`;
const readLayerCache = (uid) => {
  try {
    const raw = localStorage.getItem(LAYER_CACHE_KEY(uid));
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
};
const writeLayerCache = (uid, layers) => {
  try { localStorage.setItem(LAYER_CACHE_KEY(uid), JSON.stringify(layers)); } catch {}
};
const LAYER_EVENTS_CACHE_TTL_MS = 2 * 60 * 1000;
const LAYER_EVENTS_CACHE_KEY = (uid, layerId) => `layer-events-cache-v1:${uid}:${String(layerId || '').trim()}`;
const readLayerEventsCache = (uid, layerId) => {
  const normalizedLayerId = String(layerId || '').trim();
  if (!uid || !normalizedLayerId) return null;
  try {
    const raw = localStorage.getItem(LAYER_EVENTS_CACHE_KEY(uid, normalizedLayerId));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const expiresAt = Number(parsed?.expires_at || 0);
    if (!expiresAt || expiresAt < Date.now()) {
      localStorage.removeItem(LAYER_EVENTS_CACHE_KEY(uid, normalizedLayerId));
      return null;
    }
    const events = parsed?.events;
    return events && typeof events === 'object' ? events : null;
  } catch {
    return null;
  }
};
const writeLayerEventsCache = (uid, layerId, events) => {
  const normalizedLayerId = String(layerId || '').trim();
  if (!uid || !normalizedLayerId || !events || typeof events !== 'object') return;
  try {
    localStorage.setItem(
      LAYER_EVENTS_CACHE_KEY(uid, normalizedLayerId),
      JSON.stringify({
        expires_at: Date.now() + LAYER_EVENTS_CACHE_TTL_MS,
        events,
      })
    );
  } catch {}
};

