const normalizeVoteValue = (value) => (Number(value) === 1 ? 1 : Number(value) === -1 ? -1 : 0);
const getExploreVotesLocalKey = (userId) => `public-calendar-votes:${String(userId || 'anon')}`;
const PUBLIC_CALENDARS_CACHE_TTL = 5 * 60 * 1000;
const getPublicCalendarsCacheKey = (userId) => `public-calendars-cache:${String(userId || 'anon')}`;
const readPublicCalendarsCache = (userId) => {
  if (typeof window === 'undefined') return null;
  try {
    const raw = localStorage.getItem(getPublicCalendarsCacheKey(userId));
    const parsed = raw ? JSON.parse(raw) : null;
    if (!parsed || typeof parsed !== 'object') return null;
    const ts = Number(parsed?.ts || 0);
    const rows = Array.isArray(parsed?.rows) ? parsed.rows : null;
    const votesMode = String(parsed?.votesMode || 'db').trim() || 'db';
    if (!Number.isFinite(ts) || !rows) return null;
    return { ts, rows, votesMode };
  } catch {
    return null;
  }
};
const writePublicCalendarsCache = (userId, rows, votesMode = 'db') => {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(
      getPublicCalendarsCacheKey(userId),
      JSON.stringify({
        ts: Date.now(),
        rows: Array.isArray(rows) ? rows : [],
        votesMode: String(votesMode || 'db').trim() || 'db',
      })
    );
  } catch {}
};
const readExploreVotesLocal = (userId) => {
  if (typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(getExploreVotesLocalKey(userId));
    const parsed = raw ? JSON.parse(raw) : {};
    if (!parsed || typeof parsed !== 'object') return {};
    return Object.entries(parsed).reduce((acc, [layerId, voteValue]) => {
      const lid = String(layerId || '').trim();
      if (!lid) return acc;
      acc[lid] = normalizeVoteValue(voteValue);
      return acc;
    }, {});
  } catch {
    return {};
  }
};
const writeExploreVotesLocal = (userId, votesByLayer) => {
  if (typeof window === 'undefined') return;
  const next = Object.entries(votesByLayer || {}).reduce((acc, [layerId, voteValue]) => {
    const lid = String(layerId || '').trim();
    const normalized = normalizeVoteValue(voteValue);
    if (!lid) return acc;
    acc[lid] = normalized;
    return acc;
  }, {});
  localStorage.setItem(getExploreVotesLocalKey(userId), JSON.stringify(next));
};

const formatHighlightDateRange = (startDate, endDate) => {
  const toDate = (value) => {
    const raw = String(value || '').trim();
    if (!raw) return null;
    const parsed = /^\d{4}-\d{2}-\d{2}$/.test(raw) ? new Date(`${raw}T00:00:00`) : new Date(raw);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  };
  const start = toDate(startDate);
  const end = toDate(endDate);
  if (!start && !end) return 'Trip recap';
  const fmt = (date, withYear = false) => date.toLocaleDateString('en-US', withYear ? { month: 'short', day: 'numeric', year: 'numeric' } : { month: 'short', day: 'numeric' });
  if (start && end) {
    const sameYear = start.getFullYear() === end.getFullYear();
    return `${fmt(start)} - ${fmt(end, !sameYear)}`;
  }
  return fmt(start || end, true);
};

const buildTripHighlights = (trip, photos, itineraryItems) => {
  const tripTitle = String(trip?.name || 'Trip').trim() || 'Trip';
  const tripDatesLabel = formatHighlightDateRange(trip?.start_date, trip?.end_date);
  const safePhotos = Array.isArray(photos) ? photos.filter(Boolean) : [];
  const safeItems = Array.isArray(itineraryItems) ? itineraryItems.filter(Boolean) : [];
  const normalizeText = (...parts) => parts.map((part) => String(part || '').trim()).filter(Boolean).join(' ');
  const formatHighlightTime = (value) => {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const [hh = '0', mm = '00'] = raw.split(':');
    let hour = Number(hh);
    const minute = String(mm || '00').padStart(2, '0');
    const suffix = hour >= 12 ? 'PM' : 'AM';
    if (hour === 0) hour = 12;
    else if (hour > 12) hour -= 12;
    return `${hour}:${minute} ${suffix}`;
  };
  const foodRegex = /\b(food|restaurant|breakfast|brunch|lunch|dinner|coffee|cafe|bar|dessert|pizza|ramen|taco|bakery|wine)\b/i;
  const scenicRegex = /\b(view|scenic|sunset|sunrise|golden hour|beach|coast|lake|mountain|rooftop|lookout|vista)\b/i;
  const nightlifeRegex = /\b(bar|club|cocktail|night|late|dj|dance|speakeasy|live music)\b/i;
  const landmarkRegex = /\b(museum|park|tour|gallery|cathedral|temple|castle|bridge|market|landmark|plaza|hike|monument)\b/i;
  const socialRegex = /\b(with|friends|family|crew|together|group|party|celebration|birthday)\b/i;
  const fillerRegex = /\b(check in|check-in|hotel|airport|flight|train|taxi|uber|lyft|transfer)\b/i;
  const photoSeen = new Set();
  const dedupedPhotos = safePhotos.filter((photo) => {
    const key = [
      String(photo?.event_id || '').trim(),
      String(photo?.date || '').trim(),
      String(photo?.caption || '').trim().toLowerCase(),
      String(photo?.url || '').trim().toLowerCase(),
    ].join('|');
    if (photoSeen.has(key)) return false;
    photoSeen.add(key);
    return true;
  });
  const photosByEventId = dedupedPhotos.reduce((acc, photo) => {
    const key = String(photo?.event_id || '').trim();
    if (!key) return acc;
    if (!acc[key]) acc[key] = [];
    acc[key].push(photo);
    return acc;
  }, {});
  const photosByDate = dedupedPhotos.reduce((acc, photo) => {
    const key = String(photo?.date || '').trim();
    if (!key) return acc;
    if (!acc[key]) acc[key] = [];
    acc[key].push(photo);
    return acc;
  }, {});
  const sortedItems = [...safeItems].sort((a, b) => {
    const aDate = String(a?.date || '').trim();
    const bDate = String(b?.date || '').trim();
    if (aDate !== bDate) return aDate.localeCompare(bDate);
    return String(a?.time || '').localeCompare(String(b?.time || ''));
  });
  const uniqueLocations = Array.from(new Set([
    String(trip?.weather_location || '').trim(),
    ...sortedItems.map((item) => String(item?.location || '').trim()),
  ].filter(Boolean)));
  const classifyMoment = (text) => ({
    food: foodRegex.test(text),
    scenic: scenicRegex.test(text),
    nightlife: nightlifeRegex.test(text),
    landmark: landmarkRegex.test(text),
    social: socialRegex.test(text),
    filler: fillerRegex.test(text),
  });
  const pickHighlightLabel = (moment, isHook = false) => {
    if (isHook) return 'Best moment';
    if (moment?.traits?.food) return 'Favorite meal';
    if (moment?.traits?.scenic) return 'Golden hour';
    if (moment?.traits?.nightlife) return 'After dark';
    if (moment?.traits?.landmark) return 'Worth it';
    if (moment?.traits?.social) return 'Core memory';
    return 'Highlight';
  };
  const scorePhoto = (photo, text = '') => {
    const combined = normalizeText(text, photo?.caption);
    const traits = classifyMoment(combined);
    return (photo?.url ? 10 : 0)
      + (photo?.caption ? 6 : 0)
      + (String(photo?.caption || '').trim().length > 24 ? 2 : 0)
      + (traits.food ? 3 : 0)
      + (traits.scenic ? 4 : 0)
      + (traits.nightlife ? 3 : 0)
      + (traits.landmark ? 3 : 0)
      + (traits.social ? 2 : 0);
  };
  const moments = sortedItems.map((item, index) => {
    const itemId = String(item?.id || '').trim();
    const dateKey = String(item?.date || '').trim();
    const text = normalizeText(item?.title, item?.location, item?.notes, item?.category);
    const eventPhotos = photosByEventId[itemId] || [];
    const datePhotos = photosByDate[dateKey] || [];
    const featuredPhoto = [...eventPhotos, ...datePhotos]
      .filter((photo, photoIdx, arr) => arr.findIndex((candidate) => String(candidate?.url || '') === String(photo?.url || '')) === photoIdx)
      .sort((a, b) => scorePhoto(b, text) - scorePhoto(a, text))[0] || null;
    const traits = classifyMoment(normalizeText(text, featuredPhoto?.caption));
    const duplicatePenalty = sortedItems.findIndex((other) => normalizeText(other?.title, other?.location) === normalizeText(item?.title, item?.location)) !== index ? 2 : 0;
    const score = (featuredPhoto ? 12 : 0)
      + (featuredPhoto?.caption ? 5 : 0)
      + Math.min(eventPhotos.length + datePhotos.length, 3)
      + (traits.food ? 4 : 0)
      + (traits.scenic ? 5 : 0)
      + (traits.nightlife ? 4 : 0)
      + (traits.landmark ? 4 : 0)
      + (traits.social ? 3 : 0)
      + (/popup|special|festival|concert|celebration/i.test(text) ? 3 : 0)
      - (traits.filler ? 5 : 0)
      - duplicatePenalty;
    return {
      item,
      dateKey,
      text,
      featuredPhoto,
      traits,
      score,
      bullets: [
        normalizeText(item?.time ? formatHighlightTime(item.time) : '', item?.title),
        item?.location ? `At ${item.location}` : '',
        featuredPhoto?.caption || item?.notes || '',
      ].filter(Boolean),
    };
  });
  const rankedMoments = [...moments].sort((a, b) => b.score - a.score);
  const selectedHighlights = [];
  const usedDays = new Set();
  const usedTypes = new Set();
  rankedMoments.forEach((moment) => {
    if (selectedHighlights.length >= 3) return;
    const typeKey = moment.traits.food ? 'food'
      : moment.traits.scenic ? 'scenic'
      : moment.traits.nightlife ? 'nightlife'
      : moment.traits.landmark ? 'landmark'
      : 'general';
    const sameDayPenalty = usedDays.has(moment.dateKey);
    const sameTypePenalty = usedTypes.has(typeKey);
    if (moment.score < 4) return;
    if (sameDayPenalty && sameTypePenalty) return;
    selectedHighlights.push({ ...moment, typeKey });
    usedDays.add(moment.dateKey);
    usedTypes.add(typeKey);
  });
  const hookMoment = selectedHighlights[0] || rankedMoments[0] || null;
  const hookPhoto = hookMoment?.featuredPhoto || [...dedupedPhotos].sort((a, b) => scorePhoto(b) - scorePhoto(a))[0] || null;
  const setupBullets = selectedHighlights.slice(0, 3).map((moment) => normalizeText(
    moment?.item?.title,
    moment?.item?.location ? `@ ${moment.item.location}` : ''
  ));
  const slides = [{
    type: 'hook',
    title: hookMoment?.item?.title || tripTitle,
    subtitle: tripDatesLabel,
    caption: hookPhoto?.caption || hookMoment?.item?.notes || `The part of ${tripTitle} that still feels worth replaying.`,
    image: getTripPhotoExportUrl(hookPhoto) || null,
    imageObject: hookPhoto || null,
    meta: hookMoment?.item?.location || uniqueLocations.slice(0, 2).join(' · '),
    tag: pickHighlightLabel(hookMoment, true),
  }, {
    type: 'context',
    title: tripTitle,
    subtitle: 'Quick setup',
    caption: uniqueLocations.length > 0
      ? `A trip built around ${uniqueLocations.slice(0, 3).join(', ')}.`
      : 'A few standout stops, good meals, and the moments worth stealing.',
    image: null,
    meta: tripDatesLabel,
    tag: 'Scene setter',
    bullets: setupBullets,
  }];
  selectedHighlights.slice(0, 3).forEach((moment, index) => {
    slides.push({
      type: 'highlight',
      title: moment?.item?.title || `Highlight ${index + 1}`,
      subtitle: new Date(`${moment.dateKey}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }),
      caption: moment?.featuredPhoto?.caption || moment?.item?.notes || 'One of the moments that made the trip feel worth planning.',
      image: getTripPhotoExportUrl(moment?.featuredPhoto) || null,
      imageObject: moment?.featuredPhoto || null,
      meta: moment?.item?.location || '',
      tag: pickHighlightLabel(moment),
      bullets: moment?.bullets?.slice(0, 2),
    });
  });
  slides.push({
    type: 'end',
    title: `Steal this trip`,
    subtitle: tripTitle,
    caption: `Save the restaurants, landmarks, and standout moments from ${tripTitle}, then publish it to Explore when you're ready.`,
    image: getTripPhotoExportUrl(selectedHighlights[1]?.featuredPhoto) || getTripPhotoExportUrl(hookPhoto) || null,
    imageObject: selectedHighlights[1]?.featuredPhoto || hookPhoto || null,
    meta: uniqueLocations.slice(0, 2).join(' · '),
    tag: 'Do it again',
  });
  return slides.slice(0, 6);
};


const urlBase64ToUint8Array = (base64String) => {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i += 1) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
};

const getAccountDarkModeStorageKey = (userId) => `darkMode:${String(userId || 'guest').trim() || 'guest'}`;
const getAccountThemeModeStorageKey = (userId) => `themeMode:${String(userId || 'guest').trim() || 'guest'}`;
const THEME_MODE_OPTIONS = Object.freeze(['auto', 'dark', 'light']);
const GAUNTLET_PAIRING_PATTERNS = Object.freeze([
  Object.freeze([[0, 3], [1, 2]]),
  Object.freeze([[0, 2], [1, 3]]),
  Object.freeze([[0, 1], [2, 3]]),
]);

const shuffleGauntletIds = (ids, seed) => {
  const out = [...(ids || [])];
  let state = Math.max(1, Number(seed) || 1);
  const nextRand = () => {
    state = (state * 1664525 + 1013904223) % 4294967296;
    return state / 4294967296;
  };
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(nextRand() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
};

const getGauntletPartnerKey = (a, b) => {
  const ids = [String(a || '').trim(), String(b || '').trim()].filter(Boolean).sort();
  return ids.length === 2 ? ids.join('::') : '';
};

const buildGauntletPartnerHistory = (rounds) => {
  const history = new Map();
  (Array.isArray(rounds) ? rounds : []).forEach((round) => {
    (round?.courts || []).forEach((court) => {
      [[court?.teamA, court?.teamB]].flat().forEach((team) => {
        const ids = Array.isArray(team) ? team.map((id) => String(id || '')).filter(Boolean) : [];
        if (ids.length < 2) return;
        for (let i = 0; i < ids.length; i += 1) {
          for (let j = i + 1; j < ids.length; j += 1) {
            const key = getGauntletPartnerKey(ids[i], ids[j]);
            if (!key) continue;
            history.set(key, (history.get(key) || 0) + 1);
          }
        }
      });
    });
  });
  return history;
};

const chooseGauntletPairingPattern = ({ group, partnerHistory, roundIndex = 0, courtIndex = 0 }) => {
  const ids = Array.isArray(group) ? group.map((participant) => String(participant?.id || '')).filter(Boolean) : [];
  if (ids.length !== 4) return GAUNTLET_PAIRING_PATTERNS[0];
  const scoredPatterns = GAUNTLET_PAIRING_PATTERNS.map((pattern, patternIndex) => {
    const teamAIds = pattern[0].map((playerIndex) => ids[playerIndex]).filter(Boolean);
    const teamBIds = pattern[1].map((playerIndex) => ids[playerIndex]).filter(Boolean);
    const score =
      (partnerHistory.get(getGauntletPartnerKey(teamAIds[0], teamAIds[1])) || 0)
      + (partnerHistory.get(getGauntletPartnerKey(teamBIds[0], teamBIds[1])) || 0);
    const tiebreak = (patternIndex - ((roundIndex + courtIndex) % GAUNTLET_PAIRING_PATTERNS.length) + GAUNTLET_PAIRING_PATTERNS.length) % GAUNTLET_PAIRING_PATTERNS.length;
    return { pattern, score, tiebreak };
  });
  scoredPatterns.sort((a, b) => a.score - b.score || a.tiebreak - b.tiebreak);
  return scoredPatterns[0]?.pattern || GAUNTLET_PAIRING_PATTERNS[0];
};

const chunkIntoGauntletCourts = (participantIds, participantsById) => {
  const list = Array.isArray(participantIds) ? participantIds.map((id) => participantsById[String(id || '')]).filter(Boolean) : [];
  const courts = [];
  for (let index = 0; index < list.length; index += 4) {
    const group = list.slice(index, index + 4);
    if (group.length === 4) courts.push(group);
  }
  return courts;
};

const getGauntletByeIdsForOrder = (participantOrder, byeCount, _byeCursor = 0, existingRounds = []) => {
  const order = Array.isArray(participantOrder) ? participantOrder.map((id) => String(id || '')).filter(Boolean) : [];
  const safeByeCount = Math.max(0, Math.min(order.length, Number(byeCount) || 0));
  if (safeByeCount === 0 || order.length === 0) return [];
  // Count bye history per player ID so we rotate by identity, not list position
  const byeHistory = {};
  order.forEach((id) => { byeHistory[id] = 0; });
  (Array.isArray(existingRounds) ? existingRounds : []).forEach((round) => {
    (round?.byeIds || []).forEach((pid) => {
      const id = String(pid || '');
      if (id in byeHistory) byeHistory[id]++;
    });
  });
  // Stable sort: preserve participantOrder as tiebreaker within same bye count
  return [...order]
    .sort((a, b) => (byeHistory[a] || 0) - (byeHistory[b] || 0))
    .slice(0, safeByeCount);
};

const buildGauntletRoundFromOrder = ({ participantOrder, participantsById, roundIndex = 0, byeCursor = 0, existingRounds = [] }) => {
  const order = Array.isArray(participantOrder) ? participantOrder.map((id) => String(id || '')).filter(Boolean) : [];
  const byeCount = order.length % 4;
  const byeIds = getGauntletByeIdsForOrder(order, byeCount, byeCursor, existingRounds);
  const activeIds = order.filter((id) => !byeIds.includes(id));
  const courtGroups = chunkIntoGauntletCourts(activeIds, participantsById);
  const partnerHistory = buildGauntletPartnerHistory(existingRounds);
  return {
    index: Math.max(1, Number(roundIndex || 0) + 1),
    createdAt: new Date().toISOString(),
    finalizedAt: null,
    byeIds,
    courts: (courtGroups || []).map((group, idx) => ({
      ...(function () {
        const pattern = chooseGauntletPairingPattern({
          group,
          partnerHistory,
          roundIndex,
          courtIndex: idx,
        });
        return {
          courtNumber: idx + 1,
          playerIds: group.map((participant) => String(participant?.id || '')).filter(Boolean),
          teamA: pattern[0].map((playerIndex) => String(group[playerIndex]?.id || '')).filter(Boolean),
          teamB: pattern[1].map((playerIndex) => String(group[playerIndex]?.id || '')).filter(Boolean),
          scoreA: '',
          scoreB: '',
        };
      })(),
    })),
  };
};

const createGauntletTournament = ({ eventId, totalRounds, participants }) => {
  const safeParticipants = Array.isArray(participants) ? participants.filter((participant) => String(participant?.id || '').trim()) : [];
  const roundsTarget = Math.max(1, parseInt(String(totalRounds || ''), 10) || 1);
  const participantsById = safeParticipants.reduce((acc, participant) => {
    const id = String(participant?.id || '').trim();
    if (!id) return acc;
    acc[id] = participant;
    return acc;
  }, {});
  const participantOrder = shuffleGauntletIds(
    safeParticipants.map((participant) => String(participant?.id || '')).filter(Boolean),
    Date.now()
  );
  return {
    eventId: String(eventId || ''),
    totalRounds: roundsTarget,
    createdAt: new Date().toISOString(),
    completedAt: null,
    status: 'active',
    participants: safeParticipants,
    participantOrder,
    byeCursor: 0,
    rounds: participantOrder.length > 0 ? [buildGauntletRoundFromOrder({
      participantOrder,
      participantsById,
      roundIndex: 0,
      byeCursor: 0,
      existingRounds: [],
    })] : [],
  };
};

const getGauntletCourtResult = (court) => {
  const scoreA = parseInt(String(court?.scoreA ?? '').trim(), 10);
  const scoreB = parseInt(String(court?.scoreB ?? '').trim(), 10);
  if (!Number.isFinite(scoreA) || !Number.isFinite(scoreB) || scoreA < 0 || scoreB < 0 || scoreA === scoreB) return null;
  const teamA = Array.isArray(court?.teamA) ? court.teamA.map((value) => String(value || '')).filter(Boolean) : [];
  const teamB = Array.isArray(court?.teamB) ? court.teamB.map((value) => String(value || '')).filter(Boolean) : [];
  const teamAWon = scoreA > scoreB;
  return {
    winners: teamAWon ? teamA : teamB,
    losers: teamAWon ? teamB : teamA,
    scoreA,
    scoreB,
  };
};

const buildNextGauntletParticipantOrder = (round, participantsById, previousOrder) => {
  const results = Array.isArray(round?.courts) ? round.courts.map((court) => getGauntletCourtResult(court)) : [];
  if (results.length === 0 || results.some((result) => !result)) return null;
  const nextGroups = results.map((result, idx) => {
    const upperLosers = idx > 0 ? results[idx - 1]?.losers || [] : [];
    const lowerWinners = idx < results.length - 1 ? results[idx + 1]?.winners || [] : [];
    const ids = idx === 0
      ? [...result.winners, ...lowerWinners]
      : idx === results.length - 1
        ? [...upperLosers, ...result.losers]
        : [...upperLosers, ...lowerWinners];
    const group = ids.map((id) => participantsById[String(id || '')]).filter(Boolean);
    return group.length === 4 ? group : null;
  });
  if (nextGroups.some((group) => !group)) return null;
  const nextActiveIds = nextGroups.flatMap((group) => group.map((participant) => String(participant?.id || '')).filter(Boolean));
  const byeIds = Array.isArray(round?.byeIds) ? round.byeIds.map((id) => String(id || '')).filter(Boolean) : [];
  if (byeIds.length === 0) return nextActiveIds;
  const byeSet = new Set(byeIds);
  const activeQueue = [...nextActiveIds];
  return (previousOrder || []).map((id) => String(id || '')).filter(Boolean).map((id) => (
    byeSet.has(id) ? id : activeQueue.shift()
  )).filter(Boolean);
};

const deriveGauntletStandings = (tournament) => {
  const participants = Array.isArray(tournament?.participants) ? tournament.participants : [];
  const participantMap = participants.reduce((acc, participant) => {
    const id = String(participant?.id || '').trim();
    if (!id) return acc;
    acc[id] = participant;
    return acc;
  }, {});
  const stats = participants.reduce((acc, participant) => {
    const id = String(participant?.id || '').trim();
    if (!id) return acc;
    acc[id] = {
      id,
      name: String(participant?.displayName || participant?.name || 'Player'),
      wins: 0,
      losses: 0,
      games: 0,
      byes: 0,
      pointsFor: 0,
      pointsAgainst: 0,
      pointDiff: 0,
      courtTotal: 0,
    };
    return acc;
  }, {});

  (tournament?.rounds || []).forEach((round) => {
    if (!round?.finalizedAt) return;
    (round?.byeIds || []).forEach((playerId) => {
      const row = stats[String(playerId || '')];
      if (!row) return;
      row.byes += 1;
    });
    (round?.courts || []).forEach((court) => {
      const result = getGauntletCourtResult(court);
      if (!result) return;
      const courtNumber = Math.max(1, Number(court?.courtNumber || 1));
      (court?.teamA || []).forEach((playerId) => {
        const row = stats[String(playerId || '')];
        if (!row) return;
        row.games += 1;
        row.pointsFor += result.scoreA;
        row.pointsAgainst += result.scoreB;
        row.courtTotal += courtNumber;
        if (result.scoreA > result.scoreB) row.wins += 1;
        else row.losses += 1;
      });
      (court?.teamB || []).forEach((playerId) => {
        const row = stats[String(playerId || '')];
        if (!row) return;
        row.games += 1;
        row.pointsFor += result.scoreB;
        row.pointsAgainst += result.scoreA;
        row.courtTotal += courtNumber;
        if (result.scoreB > result.scoreA) row.wins += 1;
        else row.losses += 1;
      });
    });
  });

  return Object.values(stats)
    .map((row) => ({
      ...row,
      pointDiff: row.pointsFor - row.pointsAgainst,
      winPct: row.games > 0 ? row.wins / row.games : 0,
      averageCourt: row.games > 0 ? row.courtTotal / row.games : Number.POSITIVE_INFINITY,
      participant: participantMap[row.id] || null,
    }))
    .sort((a, b) => (
      b.winPct - a.winPct
      || b.pointDiff - a.pointDiff
      || b.pointsFor - a.pointsFor
      || a.averageCourt - b.averageCourt
      || a.name.localeCompare(b.name)
    ));
};

const normalizeStoredGauntletMap = (value) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.entries(value).reduce((acc, [eventId, tournament]) => {
    const id = String(eventId || '').trim();
    if (!id || !tournament || typeof tournament !== 'object') return acc;
    acc[id] = tournament;
    return acc;
  }, {});
};

const parseManualGauntletRoster = (value) => {
  const seen = new Set();
  return String(value || '')
    .split(/\r?\n|,/)
    .map((entry) => String(entry || '').trim())
    .filter((name) => {
      if (!name) return false;
      const key = name.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map((name, idx) => ({
      id: `manual-${idx + 1}-${name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      userId: '',
      displayName: name,
      seed: idx + 1,
    }));
};

const deriveRoundRobinStandings = (tournament) => {
  const participants = Array.isArray(tournament?.participants) ? tournament.participants : [];
  const stats = participants.reduce((acc, participant) => {
    const id = String(participant?.id || '').trim();
    if (!id) return acc;
    acc[id] = {
      id,
      displayName: String(participant?.displayName || participant?.name || 'Player'),
      wins: 0,
      losses: 0,
      pointsFor: 0,
      pointsAgainst: 0,
      played: 0,
    };
    return acc;
  }, {});

  (tournament?.rounds || []).forEach((round) => {
    (round?.matches || []).filter((match) => match?.completed).forEach((match) => {
      const scoreA = parseInt(String(match?.scoreA || ''), 10);
      const scoreB = parseInt(String(match?.scoreB || ''), 10);
      if (!Number.isFinite(scoreA) || !Number.isFinite(scoreB) || scoreA < 0 || scoreB < 0 || scoreA === scoreB) return;
      const aWon = scoreA > scoreB;
      (match?.teamA?.members || []).forEach((participant) => {
        const row = stats[String(participant?.id || '')];
        if (!row) return;
        row.played += 1;
        row.pointsFor += scoreA;
        row.pointsAgainst += scoreB;
        if (aWon) row.wins += 1;
        else row.losses += 1;
      });
      (match?.teamB?.members || []).forEach((participant) => {
        const row = stats[String(participant?.id || '')];
        if (!row) return;
        row.played += 1;
        row.pointsFor += scoreB;
        row.pointsAgainst += scoreA;
        if (!aWon) row.wins += 1;
        else row.losses += 1;
      });
    });
  });

  return Object.values(stats).sort((a, b) => (
    b.wins - a.wins
    || ((b.pointsFor - b.pointsAgainst) - (a.pointsFor - a.pointsAgainst))
    || (b.pointsFor - a.pointsFor)
    || a.displayName.localeCompare(b.displayName)
  ));
};

const buildRoundRobinRoundsForTournament = (participants, teamsOf = 2, completedRoundCount = 0) => {
  const safeParticipants = [...(Array.isArray(participants) ? participants : [])].filter((participant) => String(participant?.id || '').trim());
  if (safeParticipants.length < Math.max(2, Number(teamsOf || 2) * 2)) return [];
  const teams = [];
  if (Number(teamsOf || 2) === 1) {
    safeParticipants.forEach((participant, index) => {
      teams.push({ id: `team-${index}`, members: [participant] });
    });
  } else {
    for (let index = 0; index + 1 < safeParticipants.length; index += 2) {
      teams.push({ id: `team-${index}`, members: [safeParticipants[index], safeParticipants[index + 1]] });
    }
    if (safeParticipants.length % 2 !== 0) {
      teams.push({ id: 'team-solo', members: [safeParticipants[safeParticipants.length - 1]] });
    }
  }
  if (teams.length < 2) return [];
  const slots = teams.length % 2 === 0 ? [...teams] : [...teams, { id: 'bye', members: [], isBye: true }];
  const slotCount = slots.length;
  const rounds = [];
  const fixed = slots[0];
  const rotating = slots.slice(1);
  for (let roundIndex = 0; roundIndex < slotCount - 1; roundIndex += 1) {
    const current = [fixed, ...rotating];
    const matches = [];
    for (let matchIndex = 0; matchIndex < slotCount / 2; matchIndex += 1) {
      const teamA = current[matchIndex];
      const teamB = current[slotCount - 1 - matchIndex];
      if (teamA?.isBye || teamB?.isBye) continue;
      const absoluteRoundIndex = completedRoundCount + roundIndex;
      matches.push({
        id: `rr-r${absoluteRoundIndex}-m${matchIndex}`,
        round: absoluteRoundIndex,
        teamA,
        teamB,
        scoreA: '',
        scoreB: '',
        completed: false,
      });
    }
    if (matches.length > 0) {
      rounds.push({
        index: completedRoundCount + roundIndex,
        matches,
        finalizedAt: null,
      });
    }
    rotating.unshift(rotating.pop());
  }
  return rounds;
};

const parseManualScrambleRoster = (value) => {
  const seen = new Set();
  return String(value || '')
    .split(/\r?\n|,/)
    .map((entry) => String(entry || '').trim())
    .filter((name) => {
      if (!name) return false;
      const key = name.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map((name, idx) => ({
      id: `scramble-${idx + 1}-${name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      userId: '',
      displayName: name,
      seed: idx + 1,
    }));
};

const normalizeStoredScrambleTournament = (tournament, fallbackEventId = '') => {
  if (!tournament || typeof tournament !== 'object' || Array.isArray(tournament)) return null;
  const participants = Array.isArray(tournament.participants) ? tournament.participants.filter((participant) => participant && typeof participant === 'object') : [];
  const participantIds = Array.isArray(tournament.participantIds)
    ? tournament.participantIds.map((id) => String(id || '')).filter(Boolean)
    : participants.map((participant) => String(participant?.id || '')).filter(Boolean);
  const rounds = Array.isArray(tournament.rounds)
    ? tournament.rounds.filter((round) => round && typeof round === 'object' && !Array.isArray(round))
    : [];
  return {
    ...tournament,
    eventId: String(tournament.eventId || fallbackEventId || '').trim(),
    participants,
    participantIds,
    rounds,
    totalRounds: Math.max(1, parseInt(String(tournament.totalRounds || ''), 10) || 1),
    courtCount: Math.max(1, parseInt(String(tournament.courtCount || ''), 10) || 1),
    status: String(tournament.status || (tournament.completedAt ? 'completed' : 'active')),
  };
};

const normalizeStoredScrambleMap = (value) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.entries(value).reduce((acc, [eventId, tournament]) => {
    const id = String(eventId || '').trim();
    if (!id) return acc;
    const normalizedTournament = normalizeStoredScrambleTournament(tournament, id);
    if (!normalizedTournament) return acc;
    acc[id] = normalizedTournament;
    return acc;
  }, {});
};

const shuffleScrambleIds = (ids) => {
  const out = [...(ids || [])];
  const n = out.length;
  const getRandIndex = (() => {
    if (typeof window !== 'undefined' && window.crypto && window.crypto.getRandomValues) {
      const buf = new Uint32Array(1);
      return (max) => {
        window.crypto.getRandomValues(buf);
        // Avoid bias for small max by modulo; acceptable here for UI randomness
        return buf[0] % (max + 1);
      };
    }
    return (max) => Math.floor(Math.random() * (max + 1));
  })();
  for (let i = n - 1; i > 0; i -= 1) {
    const j = getRandIndex(i);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
};

const buildScrambleRound = ({ participantIds, roundIndex, courtCount, existingRounds = [] }) => {
  const maxCourtCount = Math.max(1, Number(courtCount || 1));
  const n = (participantIds || []).length;
  const activeMax = Math.min(n - (n % 4), maxCourtCount * 4);
  const totalByeCount = n - activeMax;

  // Count bye history so we can rotate: fewest-bye players sit out first
  const byeHistory = {};
  (participantIds || []).forEach((id) => { byeHistory[String(id || '')] = 0; });
  (Array.isArray(existingRounds) ? existingRounds : []).forEach((round) => {
    (round?.byeIds || []).forEach((pid) => {
      const id = String(pid || '');
      if (id in byeHistory) byeHistory[id]++;
    });
  });

  // Shuffle first (randomizes within same bye-count tier), then stable-sort ascending by byes
  const shuffled = shuffleScrambleIds([...(participantIds || [])]);
  shuffled.sort((a, b) => (byeHistory[String(a || '')] || 0) - (byeHistory[String(b || '')] || 0));

  const byeIds = totalByeCount > 0 ? shuffled.slice(0, totalByeCount).map((id) => String(id || '')) : [];
  const activeIds = shuffled.slice(totalByeCount);

  // Build partner history to reduce repeat pairings
  const makeKey = (a, b) => {
    const ids = [String(a || '').trim(), String(b || '').trim()].filter(Boolean).sort();
    return ids.length === 2 ? ids.join('::') : '';
  };
  const partnerHistory = new Map();
  (Array.isArray(existingRounds) ? existingRounds : []).forEach((round) => {
    (round?.courts || []).forEach((court) => {
      [[...(court?.teamA || [])], [...(court?.teamB || [])]].forEach((team) => {
        const ids = (Array.isArray(team) ? team : []).map((id) => String(id || '')).filter(Boolean);
        if (ids.length < 2) return;
        const key = makeKey(ids[0], ids[1]);
        if (!key) return;
        partnerHistory.set(key, (partnerHistory.get(key) || 0) + 1);
      });
    });
  });

  const patterns = [
    [[0, 1], [2, 3]],
    [[0, 2], [1, 3]],
    [[0, 3], [1, 2]],
  ];
  const choosePattern = (groupIds, rndSeed = 0) => {
    const scored = patterns.map((pattern, idx) => {
      const teamA = pattern[0].map((pi) => groupIds[pi]).filter(Boolean);
      const teamB = pattern[1].map((pi) => groupIds[pi]).filter(Boolean);
      const score = (partnerHistory.get(makeKey(teamA[0], teamA[1])) || 0) + (partnerHistory.get(makeKey(teamB[0], teamB[1])) || 0);
      // Tiebreaker rotates by idx and a little randomness
      const tiebreak = (idx - (rndSeed % patterns.length) + patterns.length) % patterns.length;
      return { pattern, score, tiebreak };
    });
    scored.sort((a, b) => a.score - b.score || a.tiebreak - b.tiebreak);
    return scored[0]?.pattern || patterns[0];
  };

  const courts = [];
  for (let i = 0; i < activeIds.length; i += 4) {
    const batch = activeIds.slice(i, i + 4);
    if (batch.length < 4) break;
    const pattern = choosePattern(batch, i / 4 + Number(roundIndex || 0));
    courts.push({
      courtNumber: courts.length + 1,
      teamA: pattern[0].map((pi) => batch[pi]),
      teamB: pattern[1].map((pi) => batch[pi]),
      scoreA: '',
      scoreB: '',
    });
  }
  return {
    index: Number(roundIndex || 0) + 1,
    finalizedAt: null,
    byeIds,
    courts,
  };
};

const createScrambleTournament = ({ eventId, totalRounds, courtCount, participants }) => {
  const safeParticipants = Array.isArray(participants) ? participants.filter((participant) => String(participant?.id || '').trim()) : [];
  const participantIds = safeParticipants.map((participant) => String(participant?.id || '')).filter(Boolean);
  const roundsTarget = Math.max(1, parseInt(String(totalRounds || ''), 10) || 1);
  const normalizedCourtCount = Math.max(1, parseInt(String(courtCount || ''), 10) || 1);
  return {
    eventId: String(eventId || ''),
    totalRounds: roundsTarget,
    courtCount: normalizedCourtCount,
    createdAt: new Date().toISOString(),
    completedAt: null,
    status: 'active',
    participants: safeParticipants,
    participantIds,
    rounds: participantIds.length >= 4 ? [buildScrambleRound({ participantIds, roundIndex: 0, courtCount: normalizedCourtCount, existingRounds: [] })] : [],
  };
};

const getScrambleCourtResult = (court) => {
  const scoreA = parseInt(String(court?.scoreA ?? '').trim(), 10);
  const scoreB = parseInt(String(court?.scoreB ?? '').trim(), 10);
  if (!Number.isFinite(scoreA) || !Number.isFinite(scoreB) || scoreA < 0 || scoreB < 0 || scoreA === scoreB) return null;
  return { scoreA, scoreB };
};

const deriveScrambleStandings = (tournament) => {
  const participants = Array.isArray(tournament?.participants) ? tournament.participants : [];
  const stats = participants.reduce((acc, participant) => {
    const id = String(participant?.id || '').trim();
    if (!id) return acc;
    acc[id] = {
      id,
      name: String(participant?.displayName || participant?.name || 'Player'),
      wins: 0,
      losses: 0,
      games: 0,
      byes: 0,
      pointsFor: 0,
      pointsAgainst: 0,
      pointDiff: 0,
    };
    return acc;
  }, {});

  const rounds = Array.isArray(tournament?.rounds) ? tournament.rounds : [];
  rounds.forEach((round) => {
    if (!round?.finalizedAt) return;
    (round?.byeIds || []).forEach((playerId) => {
      const row = stats[String(playerId || '')];
      if (row) row.byes += 1;
    });
    (round?.courts || []).forEach((court) => {
      const result = getScrambleCourtResult(court);
      if (!result) return;
      const teamAIds = Array.isArray(court?.teamA) ? court.teamA.map((id) => String(id || '')).filter(Boolean) : [];
      const teamBIds = Array.isArray(court?.teamB) ? court.teamB.map((id) => String(id || '')).filter(Boolean) : [];
      teamAIds.forEach((playerId) => {
        const row = stats[playerId];
        if (!row) return;
        row.games += 1;
        row.pointsFor += result.scoreA;
        row.pointsAgainst += result.scoreB;
        if (result.scoreA > result.scoreB) row.wins += 1;
        else row.losses += 1;
      });
      teamBIds.forEach((playerId) => {
        const row = stats[playerId];
        if (!row) return;
        row.games += 1;
        row.pointsFor += result.scoreB;
        row.pointsAgainst += result.scoreA;
        if (result.scoreB > result.scoreA) row.wins += 1;
        else row.losses += 1;
      });
    });
  });

  return Object.values(stats)
    .map((row) => ({
      ...row,
      participant: participants.find((participant) => String(participant?.id || '') === String(row.id || '')) || null,
      pointDiff: row.pointsFor - row.pointsAgainst,
      winPct: row.games > 0 ? row.wins / row.games : 0,
    }))
    .sort((a, b) => (
      b.winPct - a.winPct
      || b.pointDiff - a.pointDiff
      || b.pointsFor - a.pointsFor
      || a.name.localeCompare(b.name)
    ));
};

const TRIP_SEARCH_PLACE_EMOJI = {
  restaurant: '🍽️', food: '🍽️', meal_takeaway: '🍽️', meal_delivery: '🍽️',
  cafe: '☕', bakery: '🥐', bar: '🍸', night_club: '🎶',
  park: '🌿', natural_feature: '🌿', campground: '⛺', beach: '🏖️',
  tourist_attraction: '⭐', point_of_interest: '📍', museum: '🏛️', art_gallery: '🖼️',
  store: '🛍️', shopping_mall: '🛍️', clothing_store: '🛍️',
  spa: '💆', gym: '💪', stadium: '🏟️', amusement_park: '🎢',
  lodging: '🏨', movie_theater: '🎬',
};

function TripPlaceSearch({ trip, darkMode, onDragStart, onDragEnd, onTouchStart }) {
  const tripId = trip?.id || null;
  const defaultAnchor = String(trip?.weather_location || trip?.name || '').trim();

  const [query, setQuery] = React.useState('');
  const [anchor, setAnchor] = React.useState(defaultAnchor);
  const [editingAnchor, setEditingAnchor] = React.useState(false);
  const [anchorDraft, setAnchorDraft] = React.useState('');
  const [results, setResults] = React.useState([]);
  const [loading, setLoading] = React.useState(false);
  const debounceRef = React.useRef(null);
  const anchorInputRef = React.useRef(null);
  const parkEntityId = React.useRef(null);
  const parkAttractions = React.useRef(null);
  const [hasParkData, setHasParkData] = React.useState(false);

  const anchorSetByUser = React.useRef(false);

  // Sync if weather_location loads in asynchronously after mount
  React.useEffect(() => {
    if (!anchorSetByUser.current) {
      const val = String(trip?.weather_location || trip?.name || '').trim();
      if (val) setAnchor(val);
    }
  }, [trip?.weather_location, trip?.name, tripId]);

  // When anchor changes, check if it's a known theme park and pre-load its attractions
  React.useEffect(() => {
    parkEntityId.current = null;
    parkAttractions.current = null;
    setHasParkData(false);
    const a = anchor.trim();
    if (a.length < 3) return;
    let canceled = false;
    (async () => {
      try {
        const destRes = await fetch('https://api.themeparks.wiki/v1/destinations');
        const destData = await destRes.json();
        if (canceled) return;
        const aLower = a.toLowerCase();
        let match = null;
        for (const dest of (destData.destinations || [])) {
          for (const park of (dest.parks || [])) {
            const pLower = park.name.toLowerCase();
            if (pLower.includes(aLower) || aLower.includes(pLower.split(' ').slice(0, 3).join(' '))) {
              match = park;
              break;
            }
          }
          if (match) break;
        }
        if (!match || canceled) return;
        parkEntityId.current = match.id;
        const attRes = await fetch(`https://api.themeparks.wiki/v1/entity/${match.id}/children`);
        const attData = await attRes.json();
        if (canceled) return;
        const typeEmoji = { ATTRACTION: '🎢', SHOW: '🎭', RESTAURANT: '🍽️', HOTEL: '🏨', SHOP: '🛍️', MERCHANDISE: '🛍️', ENTERTAINMENT: '🎭' };
        parkAttractions.current = (attData.children || []).map((child, i) => ({
          id: `park-${child.id || i}`,
          sourceId: `park-${child.id || i}`,
          label: child.name,
          imageUrl: '',
          emoji: typeEmoji[child.entityType] || '🎢',
          type: 'photo',
          rot: ((i * 3 + 7) % 11 - 5) * 0.5,
        }));
        setHasParkData(true);
      } catch { /* not a known theme park, silent */ }
    })();
    return () => { canceled = true; };
  }, [anchor]);

  const runSearch = React.useCallback(async (q, loc) => {
    const term = q.trim();
    if (term.length < 2) { setResults([]); return; }
    setLoading(true);
    try {
      const termLower = term.toLowerCase();
      // Park attractions: sync filter from cached list
      const parkResults = (parkAttractions.current || [])
        .filter(a => a.label.toLowerCase().includes(termLower))
        .slice(0, 6);
      // Google Places: geo-aware search in parallel
      const fullQuery = loc ? `${term} in ${loc}` : term;
      const res = await fetch(`/api/places?action=textsearch&query=${encodeURIComponent(fullQuery)}`);
      const data = await res.json();
      const maxPlaces = parkResults.length > 0 ? 4 : 8;
      const places = (data.results || []).slice(0, maxPlaces).map((place, i) => {
        const photoRef = place.photos?.[0]?.photo_reference;
        const emoji = (place.types || []).map(t => TRIP_SEARCH_PLACE_EMOJI[t]).find(Boolean) || '📍';
        return {
          id: `trip-search-${place.place_id || i}`,
          sourceId: `trip-search-${place.place_id || i}`,
          label: place.name,
          imageUrl: photoRef ? `/api/places?action=photo&ref=${encodeURIComponent(photoRef)}&maxwidth=400` : '',
          emoji,
          type: 'photo',
          rot: ((i * 3 + 7) % 11 - 5) * 0.5,
        };
      });
      setResults([...parkResults, ...places]);
    } catch {
      setResults([]);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleChange = (e) => {
    const q = e.target.value;
    setQuery(q);
    clearTimeout(debounceRef.current);
    if (!q.trim()) { setResults([]); return; }
    debounceRef.current = setTimeout(() => runSearch(q, anchor), 400);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') { clearTimeout(debounceRef.current); runSearch(query, anchor); }
  };

  const handleClear = () => { setQuery(''); setResults([]); };

  const commitAnchor = () => {
    const val = anchorDraft.trim();
    setAnchor(val);
    anchorSetByUser.current = true;
    setEditingAnchor(false);
    setResults([]);
  };

  const startEditAnchor = () => {
    setAnchorDraft(anchor);
    setEditingAnchor(true);
    setTimeout(() => anchorInputRef.current?.focus(), 30);
  };

  const ts = darkMode ? 'rgba(186,230,253,0.6)' : 'rgba(12,74,110,0.55)';

  return (
    <div className="rounded-[28px] border border-sky-900/10 bg-sky-50/70 p-4 shadow-sm dark:border-sky-300/10 dark:bg-sky-950/20">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          <span className="text-[11px] uppercase tracking-[0.2em] text-sky-700/70 dark:text-sky-300/75">Search for places</span>
          {hasParkData && <span className="rounded-full bg-amber-100 px-1.5 py-0.5 text-[10px] font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-300">🎢 Park</span>}
        </div>
        {/* Editable location anchor */}
        {editingAnchor ? (
          <div className="flex items-center gap-1">
            <input
              ref={anchorInputRef}
              value={anchorDraft}
              onChange={e => setAnchorDraft(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') commitAnchor(); if (e.key === 'Escape') setEditingAnchor(false); }}
              placeholder="Disneyland, Tokyo, etc."
              className="rounded-xl border border-sky-300 bg-white px-2 py-0.5 text-xs text-gray-700 outline-none dark:border-sky-500/30 dark:bg-slate-800 dark:text-gray-200"
              style={{ width: 140 }}
            />
            <button type="button" onClick={commitAnchor} className="text-xs text-sky-600 font-semibold dark:text-sky-400">✓</button>
          </div>
        ) : (
          <button
            type="button"
            onClick={startEditAnchor}
            className="flex items-center gap-1 rounded-full px-2 py-0.5 text-xs"
            style={{ background: darkMode ? 'rgba(186,230,253,0.08)' : 'rgba(186,230,253,0.5)', color: ts }}
          >
            <span>📍</span>
            <span className="max-w-[120px] truncate">{anchor || 'Set location'}</span>
            <span style={{ opacity: 0.5 }}>✎</span>
          </button>
        )}
      </div>

      <div className="flex items-center gap-2 rounded-2xl border border-sky-200 bg-white px-3 py-2 shadow-sm dark:border-sky-300/15 dark:bg-slate-900">
        <span style={{ fontSize: 14, opacity: 0.5, flexShrink: 0 }}>🔍</span>
        <input
          value={query}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          placeholder="rides, restaurants, coffee…"
          className="flex-1 min-w-0 bg-transparent text-sm text-gray-800 placeholder-gray-400 outline-none dark:text-gray-100 dark:placeholder-gray-500"
          style={{ fontFamily: "'Caveat', cursive", fontSize: 15 }}
        />
        {loading && <span className="text-xs text-sky-400 shrink-0">…</span>}
        {query && !loading && (
          <button type="button" onClick={handleClear} className="shrink-0 text-xs text-gray-400 hover:text-gray-600 dark:text-gray-500">✕</button>
        )}
      </div>

      {results.length > 0 && (
        <>
          <div className="mt-4 flex gap-3 overflow-x-auto pb-2" style={{ scrollbarWidth: 'none' }}>
            {results.map((card) => (
              <div
                key={card.id}
                className="shrink-0 touch-none"
                draggable
                onDragStart={(e) => onDragStart(e, card)}
                onDragEnd={onDragEnd}
                onTouchStart={(e) => onTouchStart(e, card)}
              >
                <div
                  className="relative rounded-[3px] bg-white p-1 shadow-md w-24 dark:bg-slate-100"
                  style={{ transform: `rotate(${card.rot * 0.35}deg)`, cursor: 'grab' }}
                >
                  <div className="aspect-square w-full overflow-hidden rounded-[2px] bg-sky-50">
                    {card.imageUrl ? (
                      <img src={card.imageUrl} alt={card.label} className="h-full w-full object-cover" draggable={false} />
                    ) : (
                      <div className="flex h-full w-full items-center justify-center text-2xl">{card.emoji}</div>
                    )}
                  </div>
                  <div className="px-1 py-1 text-center text-[11px] text-gray-700" style={{ fontFamily: "'Caveat', cursive" }}>
                    <span className="line-clamp-2">{card.label}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
          <div className="mt-2 rounded-xl border border-dashed border-sky-200 bg-white/60 px-3 py-2 text-xs text-sky-900/70 dark:border-sky-300/15 dark:bg-white/[0.03] dark:text-sky-100/70">
            {hasParkData ? '🎢 Park attractions + nearby places. ' : ''}Drag a polaroid into Morning, Afternoon, or Evening below.
          </div>
        </>
      )}
    </div>
  );
}

function CompactKomoCardBack({ card, linkedChapterId, onFlipBack, onDataChange }) {
  const [notes, setNotes] = React.useState(() => {
    return String(card?.notes || '').trim();
  });
  const [attachment, setAttachment] = React.useState(() => {
    return String(card?.attachmentUrl || '').trim();
  });
  React.useEffect(() => {
    setNotes(String(card?.notes || '').trim());
    setAttachment(String(card?.attachmentUrl || '').trim());
  }, [card?.notes, card?.attachmentUrl, card?.id]);
  const saveNotes = (note) => {
    setNotes(note);
    onDataChange?.(linkedChapterId, card.id, { notes: note });
  };
  const saveAttachment = (dataUrl) => {
    setAttachment(dataUrl);
    onDataChange?.(linkedChapterId, card.id, { attachmentUrl: dataUrl });
  };
  return (
    <div
      className="absolute inset-0 overflow-hidden rounded-[3px] bg-amber-50 p-1.5 shadow-md dark:bg-slate-200"
      style={{ backfaceVisibility: 'hidden', WebkitBackfaceVisibility: 'hidden', transform: 'rotateY(180deg)', display: 'flex', flexDirection: 'column' }}
      onClick={(e) => e.stopPropagation()}
    >
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); onFlipBack(); }}
        className="absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-white/80 text-[10px] text-gray-500 shadow-sm"
      >
        ↩
      </button>
      <textarea
        value={notes}
        onChange={(e) => saveNotes(e.target.value)}
        onClick={(e) => e.stopPropagation()}
        placeholder="notes..."
        className="mt-4 flex-1 w-full resize-none bg-transparent text-[11px] text-gray-700 placeholder-gray-400/60 outline-none dark:text-gray-800"
        style={{ fontFamily: "'Caveat', cursive", lineHeight: '1.4' }}
        maxLength={500}
      />
      <div className="flex items-center justify-between pt-1">
        {attachment ? (
          <a href={attachment} target="_blank" rel="noopener noreferrer" onClick={(e) => e.stopPropagation()} className="block h-5 w-5 overflow-hidden rounded shadow-sm ring-1 ring-gray-200/60">
            <img src={attachment} alt="attachment" className="h-full w-full object-cover" />
          </a>
        ) : <span />}
        <label className="cursor-pointer rounded-full bg-white/70 px-1 py-0.5 text-[10px] text-gray-500 shadow-sm" title="Attach photo" onClick={(e) => e.stopPropagation()}>
          📎
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = (ev) => saveAttachment(ev.target.result);
              reader.readAsDataURL(file);
              e.target.value = '';
            }}
          />
        </label>
      </div>
    </div>
  );
}

