    const softerBg = mixHexColors(activeLayerPageTheme.accent, '#ffffff', darkMode ? 0.88 : 0.9);
    const border = mixHexColors(activeLayerPageTheme.accent, '#ffffff', darkMode ? 0.5 : 0.62);
