        if (scoreDiff !== 0) return scoreDiff;
        const upvoteDiff = Number(b?.upvote_count || 0) - Number(a?.upvote_count || 0);
        if (upvoteDiff !== 0) return upvoteDiff;
        const memberDiff = memberCountOf(b) - memberCountOf(a);
