  const finalizeScrambleRound = (eventId) => {
    const normalizedEventId = String(eventId || '').trim();
    const tournament = layerScrambles[normalizedEventId];
    if (!tournament) return;
    const rounds = Array.isArray(tournament?.rounds) ? tournament.rounds : [];
    const roundIndex = rounds.findIndex((round) => !round?.finalizedAt);
    if (roundIndex < 0) {
      setScrambleError('This scramble is already complete.');
      return;
    }
    const round = rounds[roundIndex];
    const hasInvalidCourt = (round?.courts || []).some((court) => !getScrambleCourtResult(court));
    if (hasInvalidCourt) {
      setScrambleError('Enter non-tied scores for every court before advancing.');
      return;
    }
    const updatedRounds = rounds.map((item, idx) => (
      idx === roundIndex ? { ...item, finalizedAt: new Date().toISOString() } : item
    ));
    const shouldComplete = (roundIndex + 1) >= Math.max(1, Number(tournament?.totalRounds || 1));
    const nextRound = shouldComplete
      ? null
      : buildScrambleRound({
          participantIds: tournament?.participantIds || [],
          roundIndex: roundIndex + 1,
          courtCount: tournament?.courtCount || scrambleCourtCount,
          existingRounds: updatedRounds,
        });
    setLayerScrambles((prev) => ({
      ...(prev || {}),
      [normalizedEventId]: {
        ...tournament,
        rounds: shouldComplete || !nextRound ? updatedRounds : [...updatedRounds, nextRound],
        status: shouldComplete ? 'completed' : 'active',
        completedAt: shouldComplete ? new Date().toISOString() : null,
      },
    }));
    setScrambleError('');
  };
  const resetScrambleTournament = (eventId) => {
    const normalizedEventId = String(eventId || '').trim();
    if (!normalizedEventId) return;
    setLayerScrambles((prev) => {
      const next = { ...(prev || {}) };
      delete next[normalizedEventId];
      return next;
    });
    setScrambleError('');
  };
  const removeScrambleParticipantFromTournament = (eventId, participantId) => {
    const normalizedEventId = String(eventId || '').trim();
    const normalizedParticipantId = String(participantId || '').trim();
    if (!normalizedEventId || !normalizedParticipantId) return;
    setLayerScrambles((prev) => {
      const tournament = prev?.[normalizedEventId];
      if (!tournament) return prev;
      const remainingParticipants = (tournament.participants || []).filter((participant) => String(participant?.id || '').trim() !== normalizedParticipantId);
      if (remainingParticipants.length === (tournament.participants || []).length) return prev;
      const remainingParticipantIds = remainingParticipants.map((participant) => String(participant?.id || '').trim()).filter(Boolean);
      const finalizedRounds = (tournament.rounds || []).filter((round) => round?.finalizedAt);
      const roundsCompleted = finalizedRounds.length;
      const totalRounds = Math.max(1, Number(tournament?.totalRounds || 1));
      const canContinue = remainingParticipants.length >= 4 && roundsCompleted < totalRounds;
      const nextRound = canContinue
        ? buildScrambleRound({
            participantIds: remainingParticipantIds,
            roundIndex: roundsCompleted,
            courtCount: tournament?.courtCount || scrambleCourtCount,
            existingRounds: finalizedRounds,
          })
        : null;
      return {
        ...(prev || {}),
        [normalizedEventId]: {
          ...tournament,
          participants: remainingParticipants,
          participantIds: remainingParticipantIds,
          rounds: nextRound ? [...finalizedRounds, nextRound] : finalizedRounds,
          status: nextRound ? 'active' : 'completed',
          completedAt: nextRound ? null : new Date().toISOString(),
        },
      };
    });
    setScrambleError('');
  };
  const startRoundRobinTournament = (eventId, restart = false, teamsOf = 2) => {
  const normalizedEventId = useManualRoundRobinRoster ? '__manual__' : String(eventId || selectedRoundRobinEventId || '').trim();
  if (!normalizedEventId) {
    setRoundRobinError(useManualRoundRobinRoster ? 'Enter player names first.' : 'Select a popup event first.');
    return;
  }
  let participants = [];
  if (useManualRoundRobinRoster) {
    participants = parseManualRoundRobinRoster(manualRoundRobinRosterInput);
    if (participants.length < 3) { setRoundRobinError('Need at least 3 players.'); return; }
  } else {
    const entry = eligibleRoundRobinEvents.find((item) => String(item?.eventId || '') === normalizedEventId) || null;
    if (!entry || entry.signupCount < 3) { setRoundRobinError('Need at least 3 players on the roster.'); return; }
    participants = (entry.signups || []).map((signup, idx) => ({
      id: String(
        signup?.memberId
        || signup?.signupId
        || (signup?.userId && !signup?.manual ? signup.userId : '')
        || `guest-${idx + 1}-${String(signup?.displayName || 'player').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-')}`
      ),
      userId: String(signup?.userId || ''),
      displayName: String(signup?.displayName || `Player ${idx + 1}`),
      photoUrl: String(
        signup?.photoUrl
        || signup?.photo_url
        || signup?.avatarUrl
        || signup?.avatar_url
        || ((String(signup?.userId || '') === String(user?.id || '') || String(signup?.displayName || '').trim().toLowerCase() === String(currentUser || '').trim().toLowerCase()) ? currentUserProfilePhotoUrl : '')
        || ''
      ),
      photo_url: String(signup?.photo_url || signup?.photoUrl || ''),
      avatarUrl: String(signup?.avatarUrl || signup?.avatar_url || ''),
      avatar_url: String(signup?.avatar_url || signup?.avatarUrl || ''),
    }));
  }
  const sourceSignature = buildRoundRobinSourceSignature(participants);
  if (!restart && layerRoundRobins[normalizedEventId]) {
    const existingTournament = layerRoundRobins[normalizedEventId];
    const existingSignature = String(existingTournament?.sourceSignature || buildRoundRobinSourceSignature(existingTournament?.participants || [])).trim();
    if (existingSignature !== sourceSignature || Number(existingTournament?.teamsOf || 2) !== Number(teamsOf || 2)) {
      restart = true;
    } else {
    setRoundRobinError('A round robin already exists. Reset it first.');
    return;
    }
  }
  // createRoundRobinTournament is defined inside RoundRobinPanel but we can recreate the logic here:
  const safe = participants.filter((p) => String(p?.id || '').trim());

  // Build rounds using circle method
  const teams = [];
  if (teamsOf === 1) {
    safe.forEach((p, i) => teams.push({ id: `team-${i}`, members: [p] }));
  } else {
    for (let i = 0; i + 1 < safe.length; i += 2) {
      teams.push({ id: `team-${i}`, members: [safe[i], safe[i + 1]] });
    }
    if (safe.length % 2 !== 0) {
      teams.push({ id: `team-solo`, members: [safe[safe.length - 1]] });
    }
  }
  const slots = teams.length % 2 === 0 ? [...teams] : [...teams, { id: 'bye', members: [], isBye: true }];
  const slotCount = slots.length;
  const rounds = [];
  const fixed = slots[0];
  const rotating = slots.slice(1);
  for (let r = 0; r < slotCount - 1; r++) {
    const current = [fixed, ...rotating];
    const matches = [];
    for (let i = 0; i < slotCount / 2; i++) {
      const teamA = current[i];
      const teamB = current[slotCount - 1 - i];
      if (teamA.isBye || teamB.isBye) continue;
      matches.push({ id: `rr-r${r}-m${i}`, round: r, teamA, teamB, scoreA: '', scoreB: '', completed: false });
    }
    if (matches.length > 0) rounds.push({ index: r, matches, finalizedAt: null });
    rotating.unshift(rotating.pop());
  }

  const tournament = {
    eventId: normalizedEventId,
    sourceSignature,
    createdAt: new Date().toISOString(),
    completedAt: null,
    status: 'active',
    teamsOf,
    participants: safe,
    rounds,
  };
  setLayerRoundRobins((prev) => ({ ...(prev || {}), [normalizedEventId]: tournament }));
  if (!useManualRoundRobinRoster) setSelectedRoundRobinEventId(normalizedEventId);
  setRoundRobinError('');
};

const resetRoundRobinTournament = (eventId) => {
  const normalizedEventId = String(eventId || '').trim();
  if (!normalizedEventId) return;
  setLayerRoundRobins((prev) => {
    const next = { ...(prev || {}) };
    delete next[normalizedEventId];
    return next;
  });
  setRoundRobinError('');
};

const removeRoundRobinParticipantFromTournament = (eventId, participantId) => {
  const normalizedEventId = String(eventId || '').trim();
  const normalizedParticipantId = String(participantId || '').trim();
  if (!normalizedEventId || !normalizedParticipantId) return;
  setLayerRoundRobins((prev) => {
    const tournament = prev?.[normalizedEventId];
    if (!tournament) return prev;
    const remainingParticipants = (tournament.participants || []).filter((participant) => String(participant?.id || '').trim() !== normalizedParticipantId);
    if (remainingParticipants.length === (tournament.participants || []).length) return prev;
    const teamsOf = Math.max(1, Number(tournament?.teamsOf || 2));
    const minimumPlayers = teamsOf === 1 ? 2 : 4;
    const finalizedRounds = (tournament.rounds || []).filter((round) => (round?.matches || []).length > 0 && (round.matches || []).every((match) => match?.completed));
    const futureRounds = remainingParticipants.length >= minimumPlayers
      ? buildRoundRobinRoundsForTournament(remainingParticipants, teamsOf, finalizedRounds.length)
      : [];
    const nextRounds = [...finalizedRounds, ...futureRounds];
    const allDone = nextRounds.length > 0 && nextRounds.every((round) => (round.matches || []).every((match) => match?.completed));
    return {
      ...(prev || {}),
      [normalizedEventId]: {
        ...tournament,
        participants: remainingParticipants,
        sourceSignature: buildRoundRobinSourceSignature(remainingParticipants),
        rounds: nextRounds,
        status: allDone || futureRounds.length === 0 ? 'completed' : 'active',
        completedAt: allDone || futureRounds.length === 0 ? new Date().toISOString() : null,
      },
    };
  });
  setRoundRobinError('');
};

const updateRoundRobinMatchScore = (eventId, roundIndex, matchId, scoreKey, value) => {
  const normalizedEventId = String(eventId || '').trim();
  if (!normalizedEventId || (scoreKey !== 'scoreA' && scoreKey !== 'scoreB')) return;
  const nextValue = value === '' ? '' : String(value).replace(/[^\d]/g, '');
  setLayerRoundRobins((prev) => {
    const tournament = prev?.[normalizedEventId];
    if (!tournament) return prev;
    return {
      ...(prev || {}),
      [normalizedEventId]: {
        ...tournament,
        rounds: (tournament.rounds || []).map((r) =>
          r.index !== roundIndex ? r : {
            ...r,
            matches: r.matches.map((m) =>
              m.id !== matchId ? m : { ...m, [scoreKey]: nextValue }
            ),
          }
        ),
      },
    };
  });
};

const finalizeRoundRobinMatch = (eventId, roundIndex, matchId) => {
  const normalizedEventId = String(eventId || '').trim();
  setLayerRoundRobins((prev) => {
    const tournament = prev?.[normalizedEventId];
    if (!tournament) return prev;
    let match = null;
    (tournament.rounds || []).forEach((r) => {
      if (r.index === roundIndex) match = (r.matches || []).find((m) => m.id === matchId);
    });
    if (!match) return prev;
    const a = parseInt(String(match.scoreA || ''), 10);
    const b = parseInt(String(match.scoreB || ''), 10);
    if (!Number.isFinite(a) || !Number.isFinite(b) || a < 0 || b < 0 || a === b) {
      setRoundRobinError('Enter valid non-tied scores before confirming.');
      return prev;
    }
    setRoundRobinError('');
    const updatedRounds = (tournament.rounds || []).map((r) =>
      r.index !== roundIndex ? r : {
        ...r,
        finalizedAt: r.matches.every((m) => (m.id === matchId ? true : m.completed)) ? new Date().toISOString() : r.finalizedAt || null,
        matches: r.matches.map((m) =>
          m.id !== matchId ? m : { ...m, completed: true }
        ),
      }
    );
    const allDone = updatedRounds.every((r) => r.matches.every((m) => m.completed));
    return {
      ...(prev || {}),
      [normalizedEventId]: {
        ...tournament,
        rounds: updatedRounds,
        status: allDone ? 'completed' : 'active',
        completedAt: allDone ? new Date().toISOString() : null,
      },
    };
  });
};
