              <button type="button" onClick={closeJourneyWorkoutTrackerModal} className="flex-1 rounded-2xl bg-gray-100 dark:bg-white/[0.06] px-4 py-3 text-sm font-medium text-gray-700 dark:text-gray-200">Discard</button>
